1	import { Router, type IRouter } from "express";
2	import { and, eq, desc } from "drizzle-orm";
3	import { db, entities } from "@workspace/db";
4	import { schemas } from "@workspace/api-zod";
5	import { complete, tryParseJsonArray } from "../lib/aiRouter";
6	
7	const router: IRouter = Router();
8	
9	router.get("/projects/:projectId/entities", async (req, res): Promise<void> => {
10	  const params = schemas.ListEntitiesParams.safeParse(req.params);
11	  if (!params.success) {
12	    res.status(400).json({ error: params.error.message });
13	    return;
14	  }
15	  const rows = await db
16	    .select()
17	    .from(entities)
18	    .where(eq(entities.projectId, params.data.projectId))
19	    .orderBy(desc(entities.createdAt));
20	  res.json(schemas.ListEntitiesResponse.parse(rows));
21	});
22	
23	router.post("/projects/:projectId/entities", async (req, res): Promise<void> => {
24	  const params = schemas.CreateEntityParams.safeParse(req.params);
25	  if (!params.success) {
26	    res.status(400).json({ error: params.error.message });
27	    return;
28	  }
29	  const parsed = schemas.CreateEntityBody.safeParse(req.body);
30	  if (!parsed.success) {
31	    res.status(400).json({ error: parsed.error.message });
32	    return;
33	  }
34	  const [row] = await db
35	    .insert(entities)
36	    .values({ ...parsed.data, projectId: params.data.projectId })
37	    .returning();
38	  res.status(201).json(row);
39	});
40	
41	router.patch("/projects/:projectId/entities/:entityId", async (req, res): Promise<void> => {
