40	        (err instanceof Error && /(ECONNRESET|ETIMEDOUT|EAI_AGAIN|fetch failed|network)/i.test(err.message));
41	      if (!isRetryable || attempt === IMAGE_RETRY_DELAYS_MS.length) break;
