  projectId: number;
  isExpanded: boolean;
  onToggle: () => void;
  onDelete: () => void;
  onUpdated: () => void;
  childEntities?: Entity[];
  isDeck?: boolean;
  deckOptions?: Entity[];
  onGamma: () => void;
}) {
  const queryClient = useQueryClient();
  const updateEntity = useUpdateEntity();
  const createEntity = useCreateEntity();
  const enhanceEntity = useAiEnhanceEntity();
