1	import { useEffect, useRef, useState } from "react";
2	import { useGetProject, useUpdateProject, useGetProjectStats, getGetProjectStatsQueryKey } from "@workspace/api-client-react";
3	import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
4	import { Input } from "@/components/ui/input";
5	import { Textarea } from "@/components/ui/textarea";
6	import { Label } from "@/components/ui/label";
7	import { Button } from "@/components/ui/button";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import { useDebounce } from "@/hooks/use-debounce";
10	import { AiEditTextarea } from "@/components/workspace/ai-edit-textarea";
11	import { ProjectVersions } from "@/components/workspace/project-versions";
12	import {
13	  LayoutDashboard, Activity, Users, FileText, CheckSquare, MessageSquare,
14	  Zap, Sparkles, Settings, MessageCircle, ChevronRight,
15	} from "lucide-react";
16	import { useQueryClient } from "@tanstack/react-query";
17	import { GAME_TEMPLATES, type GameTemplate } from "@/lib/game-templates";
18	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
19	
20	interface OverviewProps {
21	  projectId: number;
22	  onPromptSend: (prompt: string) => void;
23	}
24	
25	const QUICK_QUESTIONS = [
26	  "What are the biggest design risks in this game?",
27	  "How can I improve player interaction?",
28	  "What rules might conflict with each other?",
29	  "Suggest a unique mechanic based on my entities",
30	  "How does the complexity compare to similar games?",
31	];
32	
33	const QUICK_PROMPTS = [
34	  "Brainstorm core mechanics for this genre.",
35	  "Suggest 5 unique player roles.",
36	  "Draft a quick summary of the rulebook.",
37	  "What are some interesting twists for the endgame?",
38	];
39	
40	export function Overview({ projectId, onPromptSend }: OverviewProps) {
41	  const queryClient = useQueryClient();
42	  const { data: project, isLoading: projectLoading } = useGetProject(projectId);
43	  const { data: stats, isLoading: statsLoading } = useGetProjectStats(projectId);
44	  const updateProject = useUpdateProject();
45	
46	  const [formData, setFormData] = useState({
47	    name: "", description: "", gameType: "", genre: "", playerCount: "", targetDuration: "",
48	  });
49	  const [selectedTemplate, setSelectedTemplate] = useState<GameTemplate | null>(null);
50	
51	  const handleApplyTemplate = (template: GameTemplate) => {
52	    setFormData({
53	      ...formData,
54	      gameType: template.gameType,
55	      genre: template.genre,
56	      playerCount: template.playerCount,
57	      targetDuration: template.targetDuration,
58	      description: formData.description || template.description,
59	    });
60	    setSelectedTemplate(template);
61	    // Auto-save will trigger via debounce
62	  };
63	
64	  const handleSuggestFromTemplate = (template: GameTemplate) => {
65	    const prompt = `Based on the ${template.name} template, suggest entities, rules, and players for my game "${formData.name || project?.name}". Include: ${template.suggestedEntities.map(e => e.name).join(', ')}.`;
66	    onPromptSend(prompt);
67	  };
68	
69	  const debouncedName = useDebounce(formData.name, 1000);
70	  const debouncedDesc = useDebounce(formData.description, 1000);
71	  const debouncedType = useDebounce(formData.gameType, 1000);
72	  const debouncedGenre = useDebounce(formData.genre, 1000);
73	  const debouncedPlayers = useDebounce(formData.playerCount, 1000);
74	  const debouncedDuration = useDebounce(formData.targetDuration, 1000);
75	
76	  const initRef = useRef(false);
77	  const lastSavedRef = useRef({ ...formData });
78	
79	  useEffect(() => {
80	    if (project && !initRef.current) {
81	      const initialData = {
82	        name: project.name || "",
83	        description: project.description || "",
84	        gameType: project.gameType || "",
85	        genre: project.genre || "",
86	        playerCount: project.playerCount || "",
87	        targetDuration: project.targetDuration || "",
88	      };
89	      setFormData(initialData);
90	      lastSavedRef.current = initialData;
91	      initRef.current = true;
92	    }
93	  }, [project]);
94	
95	  useEffect(() => {
96	    if (!initRef.current) return;
97	
98	    const currentData = {
99	      name: debouncedName,
100	      description: debouncedDesc,
101	      gameType: debouncedType,
102	      genre: debouncedGenre,
103	      playerCount: debouncedPlayers,
104	      targetDuration: debouncedDuration,
105	    };
106	
107	    const hasChanged = Object.keys(currentData).some(
108	      (key) => currentData[key as keyof typeof currentData] !== lastSavedRef.current[key as keyof typeof lastSavedRef.current],
109	    );
110	
111	    if (hasChanged && currentData.name) {
112	      updateProject.mutate({ projectId, data: currentData });
113	      lastSavedRef.current = currentData;
114	    }
115	    // eslint-disable-next-line react-hooks/exhaustive-deps
116	  }, [debouncedName, debouncedDesc, debouncedType, debouncedGenre, debouncedPlayers, debouncedDuration, projectId]);
117	
118	  if (projectLoading) {
119	    return (
120	      <div className="space-y-4">
121	        <Skeleton className="h-32 w-full" />
122	        <Skeleton className="h-64 w-full" />
123	      </div>
124	    );
125	  }
126	
127	  const STATS = [
128	    { label: "Entities", count: stats?.entityCount, icon: LayoutDashboard, color: "text-blue-400", bg: "bg-blue-500/10" },
129	    { label: "Rules", count: stats?.ruleCount, icon: Activity, color: "text-violet-400", bg: "bg-violet-500/10" },
130	    { label: "Players", count: stats?.playerCount, icon: Users, color: "text-emerald-400", bg: "bg-emerald-500/10" },
131	    { label: "Notes", count: stats?.noteCount, icon: FileText, color: "text-amber-400", bg: "bg-amber-500/10" },
132	    { label: "Tasks", count: stats?.taskCount, icon: CheckSquare, color: "text-rose-400", bg: "bg-rose-500/10" },
133	    { label: "Messages", count: stats?.chatMessageCount, icon: MessageSquare, color: "text-sky-400", bg: "bg-sky-500/10" },
134	  ];
135	
136	  return (
137	    <div className="space-y-8 pb-8">
138	      {/* Game Templates */}
139	      <Card className="bg-card border-border border-purple-500/20">
140	        <CardHeader className="border-b border-border py-4 px-5 flex-row items-center gap-2">
141	          <Sparkles className="w-4 h-4 text-purple-400" />
142	          <div className="flex-1">
143	            <CardTitle className="text-base font-semibold flex items-center gap-2">
144	              Game Design Templates
145	              <span className="text-[10px] font-medium bg-purple-500/15 text-purple-300 border border-purple-500/30 px-1.5 py-0.5 rounded">AI-POWERED</span>
146	            </CardTitle>
147	            <p className="text-xs text-muted-foreground mt-0.5">Start with a proven game framework and customize it for your vision.</p>
148	          </div>
149	        </CardHeader>
150	        <CardContent className="px-5 py-4">
151	          <div className="space-y-3">
152	            <div className="flex gap-2">
153	              <Select onValueChange={(value) => {
154	                const template = GAME_TEMPLATES.find(t => t.id === value);
155	                if (template) handleApplyTemplate(template);
156	              }}>
157	                <SelectTrigger className="flex-1">
158	                  <SelectValue placeholder="Select a template to apply..." />
159	                </SelectTrigger>
160	                <SelectContent>
161	                  {GAME_TEMPLATES.map((template) => (
162	                    <SelectItem key={template.id} value={template.id}>
163	                      <div className="flex items-center gap-2">
164	                        <span className="font-medium">{template.name}</span>
165	                        <span className="text-xs text-muted-foreground">({template.playerCount})</span>
166	                      </div>
167	                    </SelectItem>
168	                  ))}
169	                </SelectContent>
170	              </Select>
171	            </div>
172	            
173	            {selectedTemplate && (
174	              <div className="bg-purple-500/5 border border-purple-500/20 rounded-lg p-3 space-y-2">
175	                <div className="flex items-center justify-between">
176	                  <div>
177	                    <h4 className="text-sm font-medium text-purple-300">{selectedTemplate.name}</h4>
178	                    <p className="text-xs text-muted-foreground">{selectedTemplate.description}</p>
179	                  </div>
180	                  <Button
181	                    size="sm"
182	                    variant="outline"
183	                    className="h-7 text-xs border-purple-500/30 hover:bg-purple-500/10"
184	                    onClick={() => handleSuggestFromTemplate(selectedTemplate)}
185	                  >
186	                    <Zap className="h-3 w-3 mr-1" />
187	                    AI Generate
188	                  </Button>
189	                </div>
190	                <div className="flex flex-wrap gap-1.5 mt-2">
191	                  {selectedTemplate.suggestedEntities.slice(0, 3).map((entity, i) => (
192	                    <span key={i} className="text-[10px] bg-purple-500/10 border border-purple-500/20 text-purple-300 px-2 py-0.5 rounded">
193	                      {entity.name}
194	                    </span>
195	                  ))}
196	                  {selectedTemplate.suggestedEntities.length > 3 && (
197	                    <span className="text-[10px] text-muted-foreground">+{selectedTemplate.suggestedEntities.length - 3} more</span>
198	                  )}
199	                </div>
200	              </div>
201	            )}
202	          </div>
203	        </CardContent>
204	      </Card>
