                                  <span className="absolute inset-0 flex items-center px-2 font-mono">{e.value}</span>
                                </div>
                              </div>
                            ))}
                          </div>
                        </div>
                      );
                    })}
                  </CardContent>
                </Card>
              )}
            </div>
