  const cardList = cards.length
    ? cards.map((c, i) =>
        `${i + 1}. **${c.name}**${c.subtype ? ` (${c.subtype})` : ""}${c.description ? ` — ${c.description}` : ""}${c.lore ? `\n   Lore: "${c.lore}"` : ""}`
